// Reaction catalogue wrapper: types, lookup, provenance. The data lives in reactions.gen.ts (generated by
// scripts/port-reactions.py from docs/research); nothing here retypes a number.
import type { Conf } from '../sim/types';
import type { Phase } from './species';
import { REACTIONS_GEN, REACTOR_SETS_GEN } from './reactions.gen';

/** A catalogue reaction (plain JSON). nu: products +, reactants - (may be fractional, e.g. -0.5 for 1/2 O2). */
export interface ReactionRec {
  id: string;
  /** Display equation in species ids (the player-facing form is built from i18n names later). */
  eq: string;
  nu: Readonly<Record<string, number>>;
  phase: Readonly<Record<string, Phase>>;
  tier: 'must' | 'stretch';
  reversible: boolean;
  /** Sum of nu over gas-phase species. */
  dnGas: number;
  /** Catalyst ids allowed (the catalyst data arrives with the catalyst catalogue). */
  catalysts: readonly string[];
  /** True when every species carries thermo data, so rigorous / textbook dH, dS, K(T) exist. */
  thermo: boolean;
  /** dH298 in kJ/mol, only for lab rows whose species carry molar mass only. */
  dH298book?: number;
  src: string;
  conf: Conf;
  used: string;
}

export const REACTIONS: readonly ReactionRec[] = REACTIONS_GEN as unknown as readonly ReactionRec[];
export const REACTION_IDS: readonly string[] = REACTIONS.map((r) => r.id);
export const REACTOR_SETS: Readonly<Record<string, readonly string[]>> = REACTOR_SETS_GEN as unknown as Record<string, readonly string[]>;
export const MUST_SHIP_REACTIONS: readonly ReactionRec[] = REACTIONS.filter((r) => r.tier === 'must');

const BY_ID: Record<string, ReactionRec> = {};
for (const r of REACTIONS) BY_ID[r.id] = r;

export function findReaction(id: string): ReactionRec | undefined { return Object.prototype.hasOwnProperty.call(BY_ID, id) ? BY_ID[id] : undefined; }
export function reactionOf(id: string): ReactionRec {
  const r = findReaction(id);
  if (r === undefined) throw new Error('unknown reaction: ' + id);
  return r;
}

export interface ReactionProvenanceRow { id: string; tier: 'must' | 'stretch'; src: string; conf: Conf }
/** One row per reaction for the provenance test and the Codex data page. */
export function reactionProvenanceReport(): ReactionProvenanceRow[] {
  return REACTIONS.map((r) => ({ id: r.id, tier: r.tier, src: r.src, conf: r.conf }));
}
